-- ============================================
-- 商城系统全量初始化 SQL（全新库部署用）
-- 由 mall/cmd/gen_init_sql.py 自动生成，请勿手动修改
-- 仅用于全新数据库，已有数据的库请勿执行
-- 用法: mysql -u root -p < init.sql
-- ============================================

CREATE DATABASE IF NOT EXISTS `MALL` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `MALL`;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ==================== t_mall_user ====================
CREATE TABLE t_mall_user (
	id VARCHAR(255) NOT NULL, 
	create_time DATETIME DEFAULT CURRENT_TIMESTAMP, 
	name VARCHAR(255), 
	avatar VARCHAR(500) COMMENT '头像URL', 
	phone VARCHAR(20) COMMENT '手机号', 
	wx_openid VARCHAR(255), 
	wx_unionid VARCHAR(255), 
	wx_session_key VARCHAR(255), 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== t_mall_user_address ====================
CREATE TABLE t_mall_user_address (
	id VARCHAR(255) NOT NULL, 
	create_time DATETIME DEFAULT CURRENT_TIMESTAMP, 
	update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, 
	userid VARCHAR(255), 
	name VARCHAR(255), 
	mobile VARCHAR(20), 
	province VARCHAR(30), 
	provincecode VARCHAR(30), 
	city VARCHAR(30), 
	citycode VARCHAR(30), 
	district VARCHAR(30), 
	districtcode VARCHAR(30), 
	detail VARCHAR(255), 
	is_defalut INTEGER, 
	`addressTag` VARCHAR(30), 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== t_mall_storage_config ====================
CREATE TABLE t_mall_storage_config (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	endpoint VARCHAR(512) COMMENT 'S3 端点地址', 
	access_key VARCHAR(256) COMMENT 'AccessKey ID', 
	secret_key VARCHAR(256) COMMENT 'AccessKey Secret', 
	bucket_name VARCHAR(128) COMMENT 'Bucket 名称', 
	region VARCHAR(64) COMMENT '地域', 
	public_endpoint VARCHAR(512) COMMENT '公网访问地址', 
	create_time DATETIME DEFAULT CURRENT_TIMESTAMP, 
	update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== t_mall_goods_catalog ====================
CREATE TABLE t_mall_goods_catalog (
	id VARCHAR(255) NOT NULL, 
	create_time DATETIME DEFAULT CURRENT_TIMESTAMP, 
	name VARCHAR(255), 
	parentid VARCHAR(255), 
	`level` INTEGER COMMENT '层级：1一级 2二级 3三级', 
	thumbnail VARCHAR(500) COMMENT '分类缩略图', 
	sort_order INTEGER COMMENT '排序', 
	update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== t_mall_goods_spu ====================
CREATE TABLE t_mall_goods_spu (
	id VARCHAR(255) NOT NULL, 
	spu_id VARCHAR(255) NOT NULL COMMENT 'SPU唯一标识', 
	title VARCHAR(500) NOT NULL COMMENT '商品标题', 
	category_id VARCHAR(255) COMMENT '分类ID', 
	is_put_on_sale INTEGER COMMENT '是否上架 1是 0否', 
	is_available INTEGER COMMENT '是否可用 1是 0否', 
	images TEXT COMMENT '商品图片/视频(JSON数组，第一张为主图)', 
	`desc` TEXT COMMENT '商品详情(富文本HTML)', 
	sold_num INTEGER COMMENT '已售数量', 
	is_sold_out BOOL COMMENT '是否售罄', 
	tags VARCHAR(500) COMMENT '标签(JSON数组)', 
	store_id VARCHAR(64) COMMENT '店铺ID', 
	create_time DATETIME DEFAULT CURRENT_TIMESTAMP, 
	update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, 
	min_sale_price INTEGER COMMENT '最低售价(分)', 
	max_sale_price INTEGER COMMENT '最高售价(分)', 
	stock_quantity INTEGER COMMENT '总库存', 
	freight_template_id INTEGER COMMENT '运费模板ID，0=使用默认模板', 
	delivery_type INTEGER COMMENT '配送方式 0=快递 1=同城配送 2=自提', 
	PRIMARY KEY (id), 
	CHECK (is_sold_out IN (0, 1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== t_mall_goods_sku ====================
CREATE TABLE t_mall_goods_sku (
	id VARCHAR(255) NOT NULL, 
	sku_id VARCHAR(255) NOT NULL COMMENT 'SKU唯一标识', 
	spu_id VARCHAR(255) COMMENT '关联SPU', 
	sku_image VARCHAR(500) COMMENT 'SKU图片', 
	price INTEGER COMMENT '销售价格(分)', 
	barcode VARCHAR(64) COMMENT '国际编码(条形码/EAN-13)', 
	stock_quantity INTEGER COMMENT '库存数量', 
	sold_quantity INTEGER COMMENT '已售数量', 
	spec_info TEXT COMMENT '规格信息(JSON数组)', 
	weight_value FLOAT COMMENT '重量', 
	weight_unit VARCHAR(10) COMMENT '重量单位', 
	create_time DATETIME DEFAULT CURRENT_TIMESTAMP, 
	update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, 
	PRIMARY KEY (id), 
	FOREIGN KEY(spu_id) REFERENCES t_mall_goods_spu (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== t_mall_goods_spec ====================
CREATE TABLE t_mall_goods_spec (
	id VARCHAR(255) NOT NULL, 
	spec_id VARCHAR(255) NOT NULL COMMENT '规格唯一标识', 
	spu_id VARCHAR(255) COMMENT '关联SPU', 
	title VARCHAR(100) NOT NULL COMMENT '规格名称(如颜色、尺码)', 
	spec_values TEXT COMMENT '规格值列表(JSON数组)', 
	create_time DATETIME DEFAULT CURRENT_TIMESTAMP, 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== t_mall_stock_goods ====================
CREATE TABLE t_mall_stock_goods (
	id INTEGER NOT NULL COMMENT '主键ID' AUTO_INCREMENT, 
	barcode VARCHAR(64) NOT NULL COMMENT '商品条码', 
	name VARCHAR(200) NOT NULL COMMENT '商品名称', 
	brand VARCHAR(100) COMMENT '品牌', 
	spec VARCHAR(100) COMMENT '规格', 
	unit VARCHAR(20) COMMENT '单位', 
	category VARCHAR(100) COMMENT '分类', 
	cost_price NUMERIC(10, 2) COMMENT '成本价', 
	sale_price NUMERIC(10, 2) COMMENT '参考售价', 
	stock_quantity INTEGER COMMENT '当前库存', 
	warn_threshold INTEGER COMMENT '库存预警阈值', 
	supplier VARCHAR(200) COMMENT '供应商', 
	shelf_life_days INTEGER COMMENT '保质期天数', 
	image_url VARCHAR(500) COMMENT '商品图片', 
	remark VARCHAR(500) COMMENT '备注', 
	`text` TEXT COMMENT '从商品库请求到的原始数据(JSON)', 
	`status` SMALLINT COMMENT '状态: 1=启用 0=停用', 
	is_auto_barcode SMALLINT COMMENT '条码来源: 0=手动/已有条码 1=无码商品自动生成', 
	create_time DATETIME DEFAULT CURRENT_TIMESTAMP, 
	update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== t_mall_stock_barcode_seq ====================
CREATE TABLE t_mall_stock_barcode_seq (
	id INTEGER NOT NULL COMMENT '主键，固定为1（单行计数器）' AUTO_INCREMENT, 
	barcode VARCHAR(64) NOT NULL COMMENT '最近生成的条码', 
	seq INTEGER NOT NULL COMMENT '当前条码流水号（从1开始）', 
	update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== t_mall_stock_in_order ====================
CREATE TABLE t_mall_stock_in_order (
	id INTEGER NOT NULL COMMENT '主键ID' AUTO_INCREMENT, 
	order_no VARCHAR(64) NOT NULL COMMENT '入库单号', 
	type SMALLINT COMMENT '入库类型: 1=采购入库 2=退货入库 3=调拨入库 4=盘盈入库', 
	total_quantity INTEGER COMMENT '入库总数量', 
	total_amount NUMERIC(10, 2) COMMENT '入库总金额', 
	`status` SMALLINT COMMENT '状态: 0=草稿 1=已提交 2=已取消', 
	operator_id INTEGER COMMENT '操作人ID', 
	operator_name VARCHAR(100) COMMENT '操作人姓名', 
	remark VARCHAR(500) COMMENT '备注', 
	create_time DATETIME DEFAULT CURRENT_TIMESTAMP, 
	update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== t_mall_stock_in_item ====================
CREATE TABLE t_mall_stock_in_item (
	id INTEGER NOT NULL COMMENT '主键ID' AUTO_INCREMENT, 
	order_id INTEGER NOT NULL COMMENT '关联入库单ID', 
	goods_id INTEGER NOT NULL COMMENT '关联t_mall_stock_goods.id', 
	quantity INTEGER COMMENT '入库数量', 
	cost_price NUMERIC(10, 2) COMMENT '入库成本价', 
	batch_no VARCHAR(64) COMMENT '批次号', 
	remark VARCHAR(500) COMMENT '备注', 
	create_time DATETIME DEFAULT CURRENT_TIMESTAMP, 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== t_mall_stock_log ====================
CREATE TABLE t_mall_stock_log (
	id INTEGER NOT NULL COMMENT '主键ID' AUTO_INCREMENT, 
	goods_id INTEGER NOT NULL COMMENT '关联t_mall_stock_goods.id', 
	change_qty INTEGER NOT NULL COMMENT '变动数量', 
	balance_after INTEGER COMMENT '变动后结存数量', 
	biz_type VARCHAR(32) NOT NULL COMMENT '业务类型: stock_in/stock_out/stock_check', 
	biz_no VARCHAR(64) COMMENT '业务单号', 
	operator_id INTEGER COMMENT '操作人ID', 
	operator_name VARCHAR(100) COMMENT '操作人姓名', 
	remark VARCHAR(500) COMMENT '备注', 
	create_time DATETIME DEFAULT CURRENT_TIMESTAMP, 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== t_mall_admin_user ====================
CREATE TABLE t_mall_admin_user (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	username VARCHAR(64) NOT NULL COMMENT '用户名', 
	password_hash VARCHAR(128) NOT NULL COMMENT '密码哈希', 
	avatar VARCHAR(500) COMMENT '头像URL', 
	role_id INTEGER COMMENT '角色ID', 
	`status` INTEGER COMMENT '状态 1启用 0禁用', 
	create_time DATETIME DEFAULT CURRENT_TIMESTAMP, 
	update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, 
	PRIMARY KEY (id), 
	UNIQUE (username), 
	FOREIGN KEY(role_id) REFERENCES t_mall_admin_role (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== t_mall_admin_role ====================
CREATE TABLE t_mall_admin_role (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(64) NOT NULL COMMENT '角色名称', 
	description VARCHAR(255) COMMENT '角色描述', 
	`status` INTEGER COMMENT '状态 1启用 0禁用', 
	create_time DATETIME DEFAULT CURRENT_TIMESTAMP, 
	update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, 
	PRIMARY KEY (id), 
	UNIQUE (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== t_mall_admin_menu ====================
CREATE TABLE t_mall_admin_menu (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(64) NOT NULL COMMENT '菜单名称', 
	frontpath VARCHAR(255) COMMENT '前端路由路径', 
	icon VARCHAR(64) COMMENT '图标名称', 
	parent_id INTEGER COMMENT '父菜单ID,0为顶级', 
	sort_order INTEGER COMMENT '排序号', 
	permission VARCHAR(128) COMMENT '权限标识如 goods:add', 
	visible INTEGER COMMENT '是否可见 1是 0否', 
	create_time DATETIME DEFAULT CURRENT_TIMESTAMP, 
	update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== t_mall_admin_role_menu ====================
CREATE TABLE t_mall_admin_role_menu (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	role_id INTEGER NOT NULL COMMENT '角色ID', 
	menu_id INTEGER NOT NULL COMMENT '菜单ID', 
	create_time DATETIME DEFAULT CURRENT_TIMESTAMP, 
	PRIMARY KEY (id), 
	FOREIGN KEY(role_id) REFERENCES t_mall_admin_role (id), 
	FOREIGN KEY(menu_id) REFERENCES t_mall_admin_menu (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== t_mall_system_config ====================
CREATE TABLE t_mall_system_config (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	config_key VARCHAR(128) NOT NULL COMMENT '配置键名', 
	config_value TEXT COMMENT '配置值', 
	description VARCHAR(255) COMMENT '配置说明', 
	config_group VARCHAR(64) COMMENT '配置分组 general/upload/storage/access', 
	create_time DATETIME DEFAULT CURRENT_TIMESTAMP, 
	update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, 
	PRIMARY KEY (id), 
	UNIQUE (config_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== t_mall_cart ====================
CREATE TABLE t_mall_cart (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	user_id VARCHAR(255) NOT NULL COMMENT '用户ID', 
	spu_id VARCHAR(255) NOT NULL COMMENT '商品SPU ID', 
	sku_id VARCHAR(255) NOT NULL COMMENT '商品SKU ID', 
	quantity INTEGER COMMENT '加购数量', 
	is_selected INTEGER COMMENT '是否选中 1是 0否', 
	create_time DATETIME COMMENT '创建时间', 
	update_time DATETIME COMMENT '更新时间', 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== t_mall_order ====================
CREATE TABLE t_mall_order (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	order_id VARCHAR(64) NOT NULL COMMENT '订单号', 
	user_id VARCHAR(255) NOT NULL COMMENT '用户ID', 
	total_amount INTEGER COMMENT '商品总金额(分)', 
	discount_amount INTEGER COMMENT '优惠金额(分)', 
	freight_amount INTEGER COMMENT '运费(分)', 
	pay_amount INTEGER COMMENT '实付金额(分)', 
	pay_status INTEGER COMMENT '支付状态 0未支付 1已支付 2已退款', 
	order_status INTEGER COMMENT '订单状态 0待付款 1已付款 2已发货 3已完成 4已取消', 
	consignee_name VARCHAR(100) NOT NULL COMMENT '收货人姓名', 
	consignee_mobile VARCHAR(20) NOT NULL COMMENT '收货人手机号', 
	consignee_address VARCHAR(500) NOT NULL COMMENT '收货地址', 
	remark VARCHAR(500) COMMENT '买家留言', 
	payment_method VARCHAR(32) COMMENT '支付方式', 
	paid_at DATETIME COMMENT '支付时间', 
	transaction_id VARCHAR(64) COMMENT '微信支付交易号(用于退款)', 
	shipping_company VARCHAR(100) COMMENT '物流公司', 
	shipping_no VARCHAR(100) COMMENT '物流单号', 
	delivery_type INTEGER COMMENT '配送方式 0=快递 1=同城配送 2=自提', 
	pickup_store_id INTEGER COMMENT '自提门店ID', 
	pickup_store_name VARCHAR(100) COMMENT '自提门店名称', 
	pickup_code VARCHAR(10) COMMENT '自提核销码', 
	pickup_expire_time DATETIME COMMENT '自提截止时间', 
	local_delivery_time VARCHAR(50) COMMENT '同城配送时段', 
	create_time DATETIME DEFAULT CURRENT_TIMESTAMP, 
	update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, 
	PRIMARY KEY (id), 
	UNIQUE (order_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== t_mall_order_item ====================
CREATE TABLE t_mall_order_item (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	order_id VARCHAR(64) NOT NULL COMMENT '订单号', 
	spu_id VARCHAR(255) NOT NULL COMMENT '商品SPU ID', 
	sku_id VARCHAR(255) NOT NULL COMMENT '商品SKU ID', 
	title VARCHAR(500) NOT NULL COMMENT '商品标题', 
	thumb VARCHAR(500) COMMENT '商品图片', 
	spec_label VARCHAR(200) COMMENT '规格描述', 
	price INTEGER COMMENT '成交价(分)', 
	quantity INTEGER COMMENT '购买数量', 
	subtotal INTEGER COMMENT '小计(分)', 
	create_time DATETIME DEFAULT CURRENT_TIMESTAMP, 
	PRIMARY KEY (id), 
	FOREIGN KEY(order_id) REFERENCES t_mall_order (order_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== t_mall_freight_template ====================
CREATE TABLE t_mall_freight_template (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(100) NOT NULL COMMENT '模板名称', 
	pricing_type INTEGER COMMENT '计费方式 0=固定运费 1=按件', 
	fixed_fee INTEGER COMMENT '固定运费金额(分)', 
	first_unit INTEGER COMMENT '首件数量', 
	first_fee INTEGER COMMENT '首件费用(分)', 
	continue_unit INTEGER COMMENT '续件数量', 
	continue_fee INTEGER COMMENT '续件费用(分)', 
	free_threshold INTEGER COMMENT '满额包邮门槛(分)，0=不启用', 
	is_default INTEGER COMMENT '是否默认模板 1=是 0=否', 
	create_time DATETIME DEFAULT CURRENT_TIMESTAMP, 
	update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== t_mall_freight_region ====================
CREATE TABLE t_mall_freight_region (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	template_id INTEGER NOT NULL COMMENT '关联模板ID', 
	region_code VARCHAR(20) NOT NULL COMMENT '省份编码', 
	region_name VARCHAR(50) NOT NULL COMMENT '省份名称', 
	is_free INTEGER COMMENT '是否包邮 1=是 0=按规则', 
	fixed_fee INTEGER COMMENT '该地区固定运费(分)，覆盖模板值', 
	first_fee INTEGER COMMENT '该地区首费(分)，覆盖模板值', 
	continue_fee INTEGER COMMENT '该地区续费(分)，覆盖模板值', 
	free_threshold INTEGER COMMENT '该地区包邮门槛(分)，覆盖模板值', 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== t_mall_wechat_pay_config ====================
CREATE TABLE t_mall_wechat_pay_config (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	app_id VARCHAR(128) COMMENT '微信小程序AppID', 
	mch_id VARCHAR(128) COMMENT '微信商户号', 
	mch_key TEXT COMMENT 'APIv2密钥/微信支付公钥(PEM)', 
	apiv3_key VARCHAR(64) COMMENT 'APIv3密钥(32位,解密回调)', 
	notify_url VARCHAR(512) COMMENT '支付回调URL', 
	private_key VARCHAR(4096) COMMENT '商户API V3私钥(PEM)', 
	certificate VARCHAR(4096) COMMENT '商户证书(PEM)', 
	cert_serial_no VARCHAR(128) COMMENT '商户证书序列号(自动提取)', 
	create_time DATETIME DEFAULT CURRENT_TIMESTAMP, 
	update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== t_mall_agreement ====================
CREATE TABLE t_mall_agreement (
	id INTEGER NOT NULL COMMENT '主键ID' AUTO_INCREMENT, 
	type VARCHAR(32) NOT NULL COMMENT '类型: agreement=用户协议 privacy=隐私政策', 
	title VARCHAR(255) NOT NULL COMMENT '标题', 
	content TEXT COMMENT '内容', 
	version VARCHAR(32) NOT NULL COMMENT '版本号', 
	`status` SMALLINT NOT NULL COMMENT '状态: 1=启用 0=停用', 
	create_time DATETIME COMMENT '创建时间', 
	update_time DATETIME COMMENT '更新时间', 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== regions ====================
CREATE TABLE regions (
	id VARCHAR(100) NOT NULL COMMENT '主键ID', 
	code VARCHAR(20) NOT NULL COMMENT '行政区划代码', 
	name VARCHAR(100) NOT NULL COMMENT '名称', 
	parent_code VARCHAR(20) COMMENT '父级代码', 
	`level` VARCHAR(1) NOT NULL COMMENT '层级：1-省/直辖市，2-市，3-区/县', 
	full_name VARCHAR(255) COMMENT '完整名称', 
	created_at TIMESTAMP NULL DEFAULT NOW() COMMENT '创建时间', 
	updated_at TIMESTAMP NULL DEFAULT NOW() ON UPDATE NOW() COMMENT '更新时间', 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==================== t_mall_task ====================
CREATE TABLE t_mall_task (
	id VARCHAR(255) NOT NULL, 
	create_time DATETIME DEFAULT CURRENT_TIMESTAMP, 
	name VARCHAR(255), 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


